#!/usr/bin/env node
// Regenerates src/lib/hanabi/variantData.ts from hanab.live's upstream JSON.
//
//   node tools/gen-variants.mjs
//
// Needs network access. Run it when hanab.live adds suits or variants; the
// generated file is committed so the app itself never hits the network.
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const BASE =
  "https://raw.githubusercontent.com/Hanabi-Live/hanabi-live/main/packages/game/src/json";
const OUT = fileURLToPath(new URL("../src/lib/hanabi/variantData.ts", import.meta.url));

const fetchJson = async (name) => {
  const res = await fetch(`${BASE}/${name}`);
  if (!res.ok) throw new Error(`${name}: ${res.status} ${res.statusText}`);
  return res.json();
};

const [variants, suits, colors] = await Promise.all(
  ["variants.json", "suits.json", "colors.json"].map(fetchJson),
);

const colorByName = Object.fromEntries(colors.map((c) => [c.name, c]));

// hanab.live derives these suit behaviours from the suit name; scala-bot does the
// same (see Variant.scala). Mirror it so our clue logic matches the analyser's.
const WHITISH = /White|Gray|Light|Null/;
const RAINBOWISH = /Rainbow|Omni/;
const PINKISH = /Pink|Omni/;
const BROWNISH = /Brown|Muddy|Cocoa|Null/;
const DARK = /Black|Dark|Gray|Cocoa/;
const PRISM = /Prism/;
const NO_COLOUR = /White|Gray|Light|Null|Rainbow|Omni|Prism/;

const stripName = (n) =>
  n.startsWith("Dark ") ? n.slice(5) : n.startsWith("Light ") ? n.slice(6) : n;

// scala-bot models a colour clue as an index into the variant's colourable suits,
// which is only correct when suit -> clue colour is 1:1. That rules out the
// ambiguous/dual-colour families (Tomato clued by Red, Yam clued by Red or
// Yellow, ...) but keeps suits whose clue colour is simply their own name.
const usable = new Map();
for (const s of suits) {
  if (s.name === "Unknown") continue;
  const cc = s.clueColors;
  if (cc && (cc.length !== 1 || cc[0] !== stripName(s.name))) continue;
  usable.set(s.name, s);
}

// A "simple" variant carries no extra rules (no special ranks, no clue starvation,
// no critical rank...), so its behaviour is fully described by its suit list.
const isSimple = (v) =>
  Object.keys(v).every((k) => ["id", "newID", "name", "suits"].includes(k));

const chosen = variants.filter(
  (v) =>
    isSimple(v) &&
    v.suits.length >= 3 &&
    v.suits.length <= 6 &&
    v.suits.every((n) => usable.has(n)),
);

const suitOrder = [];
for (const v of chosen) for (const n of v.suits) if (!suitOrder.includes(n)) suitOrder.push(n);

const abbr = (s) =>
  s.abbreviation ?? colorByName[stripName(s.name)]?.abbreviation ?? stripName(s.name)[0].toUpperCase();

const fill = (s) => {
  if (s.fill === "multi") return s.fillColors;
  if (s.fill) return [s.fill];
  const c = colorByName[stripName(s.name)];
  if (!c) throw new Error(`no fill for ${s.name}`);
  return [c.fill];
};

const suitDefs = suitOrder.map((n) => {
  const s = usable.get(n);
  return {
    name: s.name,
    display: s.displayName ?? s.name,
    abbr: abbr(s),
    fill: fill(s),
    clueColor: s.clueColors?.[0] ?? (NO_COLOUR.test(s.name) ? null : s.name),
    oneOfEach: !!(s.oneOfEach || DARK.test(s.name)),
    allClueColors: !!(s.allClueColors || RAINBOWISH.test(s.name)),
    noClueColors: !!(s.noClueColors || WHITISH.test(s.name)),
    allClueRanks: !!(s.allClueRanks || PINKISH.test(s.name)),
    noClueRanks: !!(s.noClueRanks || BROWNISH.test(s.name)),
    prism: !!(s.prism || PRISM.test(s.name)),
  };
});

const idx = Object.fromEntries(suitOrder.map((n, i) => [n, i]));

const out = [
  "// AUTO-GENERATED by tools/gen-variants.mjs from hanab.live's upstream",
  "// variants.json / suits.json / colors.json. Do not edit by hand.",
  "//",
  "// Only variants whose suits map 1:1 onto clue colours are included, because",
  "// that is the subset the scala-bot analyser (and this app's clue logic) models",
  "// correctly. Variant names are verbatim so exports import cleanly on hanab.live.",
  "",
  "export interface SuitDef {",
  "  /** hanab.live suit name, e.g. `Dark Rainbow`. */",
  "  readonly name: string;",
  "  readonly display: string;",
  "  /** Single letter drawn on the card face. */",
  "  readonly abbr: string;",
  "  /** One colour, or several for a multicolour gradient. */",
  "  readonly fill: readonly string[];",
  "  /** Colour clue that names this suit, or null if no colour clue does. */",
  "  readonly clueColor: string | null;",
  "  readonly oneOfEach: boolean;",
  "  readonly allClueColors: boolean;",
  "  readonly noClueColors: boolean;",
  "  readonly allClueRanks: boolean;",
  "  readonly noClueRanks: boolean;",
  "  readonly prism: boolean;",
  "}",
  "",
  "export const SUITS: readonly SuitDef[] = [",
  ...suitDefs.map(
    (s) =>
      `  { name: ${JSON.stringify(s.name)}, display: ${JSON.stringify(s.display)}, abbr: ${JSON.stringify(s.abbr)}, fill: ${JSON.stringify(s.fill)}, clueColor: ${JSON.stringify(s.clueColor)}, oneOfEach: ${s.oneOfEach}, allClueColors: ${s.allClueColors}, noClueColors: ${s.noClueColors}, allClueRanks: ${s.allClueRanks}, noClueRanks: ${s.noClueRanks}, prism: ${s.prism} },`,
  ),
  "];",
  "",
  "/** `[hanab.live variant name, suit indices into SUITS]`. */",
  "export type VariantDef = readonly [name: string, suits: readonly number[]];",
  "",
  "export const VARIANTS: readonly VariantDef[] = [",
  ...chosen.map((v) => `  [${JSON.stringify(v.name)}, [${v.suits.map((n) => idx[n]).join(",")}]],`),
  "];",
  "",
].join("\n");

writeFileSync(OUT, out);
console.log(`wrote ${chosen.length} variants and ${suitDefs.length} suits to ${OUT}`);
